using RailwayWebBuilderCore.Enums;

namespace RailwayWebBuilderCore._SiteData.ModelRailways.Layouts;

internal class Sheperdswell : LayoutBase
{
    public Sheperdswell()
    {
        Name = LayoutNamesEnums.Sheperdswell;
        Description = "The original plan for this layout was to use the old East Kent Railway as a basis, but it has become more of a near-prototype model of the old Colonel Stephens line that lasted into nationalisation. Most of the line shut in the early 1950s, the truncated remainder serving Tilmanstone colliery until the mid-1980s; the passenger service finished not long after nationalisation in 1948 and the loco shed was demolished a few years later. Today the 2.5 miles between Shepherdswell and Eythorne is a preserved railway. To make operation more interesting the history has been changed so that workmen's trains still run and the line was never nationalised, with the engine shed remaining in use longer, maintaining industrial locomotives for other lines, and coal trains swapping locomotives in the yard with the occasional box van to and from the colliery. Control is by Digitrax DCC with touch screen PCs used to monitor and control the layout, and some locomotives are sound fitted. As the layout is set in the early 1960s, around the time the Kent main lines were electrified, both steam and diesel locomotives can be seen at work.";
    }
}
